def semver_sort(versions):
    def parse_version(v):
        # Split build metadata first
        if '+' in v:
            version_part, build = v.split('+', 1)
        else:
            version_part = v

        # Split pre-release
        if '-' in version_part:
            base_part, prerelease = version_part.split('-', 1)
        else:
            base_part = version_part
            prerelease = None

        # Parse MAJOR.MINOR.PATCH
        parts = base_part.split('.')
        major = int(parts[0])
        minor = int(parts[1])
        patch = int(parts[2])

        # Parse pre-release identifiers
        if prerelease:
            identifiers = prerelease.split('.')
        else:
            identifiers = None

        return (major, minor, patch, prerelease, identifiers)

    def compare_prerelease(id1, id2):
        # Check if identifiers are all digits
        is_digit1 = id1.isdigit()
        is_digit2 = id2.isdigit()

        if is_digit1 and is_digit2:
            # Both numeric: compare numerically
            return int(id1) - int(id2)
        elif is_digit1:
            # id1 is numeric, id2 is not: numeric sorts first
            return -1
        elif is_digit2:
            # id2 is numeric, id1 is not: numeric sorts first
            return 1
        else:
            # Both non-numeric: compare lexically
            if id1 < id2:
                return -1
            elif id1 > id2:
                return 1
            else:
                return 0

    def sort_key(item):
        idx, v = item
        major, minor, patch, prerelease, identifiers = parse_version(v)

        # Base comparison: major, minor, patch
        base = (major, minor, patch)

        # Pre-release comparison
        # A version without pre-release sorts after one with pre-release
        # So we use a tuple where False < True for has_prerelease
        has_prerelease = prerelease is not None

        if has_prerelease:
            # Create comparable pre-release tuple
            pre_tuple = []
            for identifier in identifiers:
                if identifier.isdigit():
                    pre_tuple.append((0, int(identifier)))  # numeric: type 0
                else:
                    pre_tuple.append((1, identifier))  # non-numeric: type 1
            pre_key = (True, tuple(pre_tuple))
        else:
            pre_key = (False, ())

        # Return tuple for sorting: (major, minor, patch, has_prerelease, pre_tuple, original_index)
        return (base[0], base[1], base[2], has_prerelease, pre_key[1], idx)

    indexed = [(i, v) for i, v in enumerate(versions)]
    sorted_indexed = sorted(indexed, key=sort_key)
    return [v for _, v in sorted_indexed]

